stepRepeat13.harness:
"""Đo 13 solve S&R lạnh trên đúng file khách, không render hoặc persist manifest.

`PRYNX_BENCH_OUTER_WORKERS` chọn số job đồng thời; `PRYNX_BENCH_PER_JOB_GRANT`
chọn worker native của từng job. Mặc định 1/auto giữ nguyên đường production tuần tự.
"""

from __future__ import annotations

import hashlib
import json
import os
import runpy
import sys
import time
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
BACKEND = ROOT / "backend"
if str(BACKEND) not in sys.path:
    sys.path.insert(0, str(BACKEND))

import pdfcompare_native

from app.core import nesting_production_orchestrator as orchestrator
from app.core.nesting_production_pipeline import solve_production_nesting_job
from app.core.nesting_source_pin import discard_source_pin
from app.workers.nup_true_shape_nesting import build_true_shape_nesting_jobs

PROBE = runpy.run_path(str(BACKEND / ".audit-tmp" / "verify_motif_full13.py"))
SOURCE = Path(PROBE["SOURCE"])
SETTINGS = dict(PROBE["SETTINGS"])
OUTER_WORKERS = max(1, int(os.environ.get("PRYNX_BENCH_OUTER_WORKERS", "1")))
PER_JOB_GRANT = max(1, int(os.environ.get("PRYNX_BENCH_PER_JOB_GRANT", "1")))


def _number(value: object) -> float | int | None:
    if isinstance(value, bool) or value is None:
        return None
    try:
        number = float(value)
    except (TypeError, ValueError):
        return None
    return int(number) if number.is_integer() else round(number, 3)


def _microseconds_to_ms(value: object) -> float | int | None:
    number = _number(value)
    return None if number is None else round(float(number) / 1000.0, 3)


def _pose_digest(manifest: dict) -> str:
    placements = [
        {
            "partId": item.get("partId"),
            "sheetIndex": item.get("sheetIndex"),
            "pose": item.get("pose"),
        }
        for item in (manifest.get("placements") or ())
    ]
    payload = json.dumps(
        placements, sort_keys=True, separators=(",", ":"), ensure_ascii=False
    ).encode("utf-8")
    return "sha256:" + hashlib.sha256(payload).hexdigest()


def _row_from_session(
    index: int,
    session: object,
    wall_ms: float,
) -> dict[str, object]:
    diagnostics = session.solved.runtime_diagnostics
    phases = diagnostics.get("phaseTimings") or {}
    native_boundary = diagnostics.get("nativeBoundaryTimings") or {}
    production_boundary = diagnostics.get("productionBoundaryTimings") or {}
    runtime_control = diagnostics.get("runtimeControl") or {}
    nfp = (diagnostics.get("nfpDiagnostics") or {}).get("baseline") or {}
    manifest = session.solved.manifest
    stats = manifest.get("stats") or {}
    solve_wall_ms = float(production_boundary.get("solveProductionWallMs") or 0.0)
    return {
        "page": index + 1,
        "wallMs": wall_ms,
        "solveProductionWallMs": _number(solve_wall_ms),
        "preSolvePythonMs": round(max(0.0, wall_ms - solve_wall_ms), 3),
        "nativeTotalMs": _number(native_boundary.get("nativeTotalMs")),
        "requestPreparationMs": _number(
            native_boundary.get("requestPreparationMs")
        ),
        "manifestSerializationMs": _number(
            native_boundary.get("manifestSerializationMs")
        ),
        "postNativeWallMs": _number(production_boundary.get("postNativeWallMs")),
        "workerGrant": _number(runtime_control.get("workerGrant")),
        "baselineMs": _number(phases.get("baselineMs")),
        "baselineValidationMs": _number(phases.get("baselineValidationMs")),
        "rotationProbeMs": _number(phases.get("rotationProbeMs")),
        "searchMs": _number(phases.get("searchMs")),
        "publicationMs": _number(phases.get("publicationMs")),
        "nfpBuildCpuMs": _microseconds_to_ms(nfp.get("nfpBuildTimeUs")),
        "differenceCpuMs": _microseconds_to_ms(nfp.get("differenceTimeUs")),
        "feasibleRegionCalls": _number(nfp.get("feasibleRegionCalls")),
        "cacheHits": _number(nfp.get("cacheHits")),
        "cacheMisses": _number(nfp.get("cacheMisses")),
        "placedCount": int(stats.get("placedCount") or 0),
        "poseDigest": _pose_digest(manifest),
    }


def _solve_one(index: int, job: object) -> dict[str, object]:
    session = None
    started = time.perf_counter()
    try:
        session = solve_production_nesting_job(job)
        wall_ms = round((time.perf_counter() - started) * 1000.0, 3)
        return _row_from_session(index, session, wall_ms)
    finally:
        if session is not None:
            for pin in session.source_pins:
                discard_source_pin(pin)


def main() -> None:
    capabilities = json.loads(pdfcompare_native.MixedNestingRun.capabilities())
    jobs = build_true_shape_nesting_jobs(str(SOURCE), SETTINGS)
    if len(jobs) != 13:
        raise RuntimeError(f"Cần đúng 13 job S&R, nhận {len(jobs)}.")

    production_batch = os.environ.get("PRYNX_BENCH_PRODUCTION_BATCH", "") == "1"
    original_plan_hardware = orchestrator.plan_hardware
    batch_sessions: list[object] = []
    if OUTER_WORKERS > 1 and not production_batch:
        # PERF (audit 2026-09-01 §SR13-WAVE-PROBE): chỉ probe chia tổng grant;
        # production vẫn dùng planner thật cho tới khi A/B chứng minh pose bất biến.
        orchestrator.plan_hardware = lambda request: original_plan_hardware(
            request, cpu_count=PER_JOB_GRANT + 1
        )

    total_started = time.perf_counter()
    try:
        if production_batch:
            from app.workers.nup_true_shape_nesting import (
                _solve_step_repeat_sessions,
            )

            batch_sessions = _solve_step_repeat_sessions(
                jobs,
                cancel_event=None,
                progress_callback=None,
            )
            rows = [
                _row_from_session(
                    index,
                    session,
                    float(
                        (
                            session.solved.runtime_diagnostics.get(
                                "productionBoundaryTimings"
                            )
                            or {}
                        ).get("solveProductionWallMs")
                        or 0.0
                    ),
                )
                for index, session in enumerate(batch_sessions)
            ]
        elif OUTER_WORKERS == 1:
            rows = [_solve_one(index, job) for index, job in enumerate(jobs)]
        else:
            with ThreadPoolExecutor(
                max_workers=min(OUTER_WORKERS, len(jobs)),
                thread_name_prefix="prynx-sr-bench",
            ) as executor:
                futures = [
                    executor.submit(_solve_one, index, job)
                    for index, job in enumerate(jobs)
                ]
                rows = [future.result() for future in futures]

        total_wall_ms = round((time.perf_counter() - total_started) * 1000.0, 3)
        rows.sort(key=lambda row: int(row["page"]))
        for row in rows:
            print(json.dumps(row, ensure_ascii=False), flush=True)

        summary = {
            "baselineVersion": capabilities["algorithmVersions"]["baselineVersion"],
            "nativeBuildIdentity": capabilities.get("nativeBuildIdentity"),
            "productionBatch": production_batch,
            "outerWorkers": OUTER_WORKERS,
            "requestedPerJobGrant": PER_JOB_GRANT if OUTER_WORKERS > 1 else None,
            "totalRequestedGrant": (
                OUTER_WORKERS * PER_JOB_GRANT if OUTER_WORKERS > 1 else None
            ),
            "totalWallMs": total_wall_ms,
            "sumSolveWallMs": round(sum(float(row["wallMs"]) for row in rows), 3),
            "sumBaselineMs": round(
                sum(float(row["baselineMs"] or 0.0) for row in rows), 3
            ),
            "sumSearchMs": round(sum(float(row["searchMs"] or 0.0) for row in rows), 3),
            "workerGrants": [row["workerGrant"] for row in rows],
            "placedCounts": [row["placedCount"] for row in rows],
            "poseDigests": [row["poseDigest"] for row in rows],
        }
        print("SUMMARY " + json.dumps(summary, ensure_ascii=False), flush=True)
    finally:
        orchestrator.plan_hardware = original_plan_hardware
        if batch_sessions:
            from app.workers.nup_true_shape_nesting import (
                _discard_step_repeat_sessions,
            )

            _discard_step_repeat_sessions(batch_sessions)


if __name__ == "__main__":
    main()
